const search = document.querySelector('#song-query');
const codeSearch = document.querySelector('#song-code');
const language = document.querySelector('#song-lang');
const mood = document.querySelector('#song-mood');
const genre = document.querySelector('#song-genre');
const era = document.querySelector('#song-era');
const resetFilters = document.querySelector('#song-reset-filters');
const filters = [language, mood, genre, era];
const randomButton = document.querySelector('#song-random');
const randomPick = document.querySelector('#song-random-pick');
let lastPick = null;
const suggestions = document.querySelector('#song-suggestions');
const list = document.querySelector('#song-list');
const count = document.querySelector('#song-count');
const prev = document.querySelector('#song-prev');
const next = document.querySelector('#song-next');
const pageSize = 12;
let page = 0;
let selectedArtist = null;
let lyricMatches = null;

const aliases = {
  'женя белоусов': ['евгений белоусов', 'genya belousov'],
  'валерий сюткин': ['сюткин и ко', 'syutkin', 'valery syutkin', 'valeriy syutkin'],
  'браво': ['bravo'],
  'кипелов': ['валерий кипелов', 'kipelov', 'valery kipelov', 'valeriy kipelov'],
  'чиж & co': ['чиж', 'чиж и ко', 'чиж со', 'чиж ко', 'chizh', 'сергей чиграков'],
  'наутилус помпилиус': ['нау', 'наутилус', 'бутусов'],
  'воскресение': ['воскресенье', 'романов'],
  'аукцыон': ['аукцион', 'auktyon'],
  'король и шут': ['киш', 'кишъ', 'шкиш', 'korol i shut', 'горшок'],
  'валерий меладзе': ['меладзе', 'meladze', 'валера меладзе'],
  'кино': ['kino', 'цой', 'виктор цой', 'tsoi'],
  'би 2': ['би2', 'bi2', 'bi 2'],
  'руки вверх': ['рукивверх', 'жуков', 'сергей жуков'],
  'макsим': ['максим', 'максим певица', 'maksim'],
  'abba': ['абба'],
  'queen': ['квин'],
  'the beatles': ['битлз', 'битлс'],
};

function normalize(text) {
  return text.toLocaleLowerCase('ru').normalize('NFD')
    .replace(/\p{Diacritic}/gu, '').replace(/[ьъ]/g, '')
    .replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
}

function oneEditAway(a, b) {
  if (Math.abs(a.length - b.length) > 1) return false;
  let i = 0, j = 0, edits = 0;
  while (i < a.length && j < b.length) {
    if (a[i] === b[j]) { i++; j++; continue; }
    if (++edits > 1) return false;
    if (a.length === b.length && a[i] === b[j + 1] && a[i + 1] === b[j]) {
      i += 2; j += 2; continue;
    }
    if (a.length >= b.length) i++;
    if (b.length >= a.length) j++;
  }
  return edits + (a.length - i) + (b.length - j) <= 1;
}

const aliasesByArtist = new Map(Object.entries(aliases).map(([name, variants]) =>
  [normalize(name), variants.map(normalize)]));

const artistCounts = new Map();
for (const song of songs) {
  artistCounts.set(song.artist, (artistCounts.get(song.artist) ?? 0) + 1);
}

function indexSong(song, id) {
  const artist = normalize(song.artist);
  const title = normalize(song.title);
  const names = [artist, title, ...(aliasesByArtist.get(artist) ?? []), ...(song.aliases ?? []).map(normalize)];
  return { song, id, artist, title, names, words: names.join(' ').split(' ') };
}
const indexed = songs.map(indexSong);
const entriesByCode = new Map(indexed.map(entry => [entry.song.code, entry]));

function rank(entry, query) {
  if (!query) return 0;
  if (entry.names.includes(query)) return 0;
  if (entry.names.some(name => name.startsWith(query))) return 1;
  const terms = query.split(' ');
  if (terms.every(term => entry.words.some(word => word.startsWith(term)))) return 2;
  if (terms.every(term => entry.names.some(name => name.includes(term)))) return 3;
  if (terms.every(term => entry.words.some(word => word.startsWith(term)
    || (term.length >= 4 && oneEditAway(term, word.slice(0, term.length)))))) return 4;
  return Infinity;
}

function renderSuggestions(container, matches, query, selectLabel) {
  const labels = query.length < 2 ? [] : [...new Set(matches.flatMap(({entry}) =>
    entry.artist.includes(query) || entry.names.slice(2).some(name => name.startsWith(query))
      ? [entry.song.artist, entry.song.title] : [entry.song.title, entry.song.artist]
  ))].slice(0, 6);
  container.replaceChildren(...labels.map(label => {
    const button = document.createElement('button');
    button.type = 'button';
    button.textContent = label;
    button.addEventListener('click', () => selectLabel(label));
    return button;
  }));
  container.hidden = labels.length === 0;
}

function getMatches() {
  const codeQuery = codeSearch.value.trim();
  if (codeQuery) {
    const validCode = /^[0-9]{4}$/.test(codeQuery) && codeQuery !== '0000';
    const entry = validCode ? entriesByCode.get(codeQuery) : undefined;
    return {matches: entry ? [{entry, score: 0}] : [], query: '', codeQuery, validCode};
  }
  const query = normalize(search.value);
  const matches = indexed
    .filter(({song}) => (!selectedArtist || song.artist === selectedArtist)
      && (!language.value || (language.value === 'en'
        ? song.lang === 'foreign' && !song.nonEnglish : song.lang === 'ru'))
      && (!mood.value || song.tags.includes(mood.value))
      && (!genre.value || song.genres.includes(genre.value) || song.screen === genre.value)
      && (!era.value || (song.year && (era.value === 'old'
        ? song.year < 1980 : Math.floor(song.year / 10) * 10 === Number(era.value)))))
    .map(entry => ({entry, score: lyricMatches
      ? lyricMatches.get(entry.id) ?? Infinity : selectedArtist ? 0 : rank(entry, query)}))
    .filter(match => Number.isFinite(match.score))
    .sort((a, b) => a.score - b.score);
  const seen = new Set();
  return {matches: matches.filter(({entry}) => {
    const key = entry.artist + '\u0000' + entry.title;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  }), query};
}

function songRow(song) {
    const row = document.createElement('li');
    const link = document.createElement('a');
    const label = document.createElement('span');
    const title = document.createElement('strong');
    const code = document.createElement('span');
    const byline = document.createElement('div');
    byline.className = 'song-byline';
    const canBrowseArtist = artistCounts.get(song.artist) > 1
      && !song.screen && song.artist !== 'Народная' && song.artist !== 'Traditional';
    const artist = document.createElement(canBrowseArtist ? 'button' : 'span');
    const action = document.createElement('span');
    const query = song.artist === 'Народная' || song.artist === 'Traditional'
      ? song.title : (song.credit || song.artist) + ' ' + song.title;
    link.href = song.video
      ? 'https://www.youtube.com/watch?v=' + song.video
      : 'https://www.youtube.com/results?search_query='
        + encodeURIComponent(query + (song.lang === 'ru' ? ' караоке с текстом' : ' karaoke lyrics'));
    link.target = '_blank';
    link.rel = 'noopener noreferrer';
    title.textContent = song.title;
    label.className = 'song-heading';
    code.className = 'song-code';
    code.textContent = song.code;
    code.setAttribute('aria-label', 'Код песни: ' + song.code);
    artist.textContent = song.credit || song.artist;
    if (canBrowseArtist) {
      artist.type = 'button';
      artist.setAttribute('aria-label', 'Все песни исполнителя ' + song.artist);
      artist.addEventListener('click', () => {
        clearLyrics();
        codeSearch.value = '';
        selectedArtist = song.artist;
        search.value = song.artist;
        page = 0;
        renderSongs();
        search.focus();
      });
    }
    byline.append(artist);
    if (song.year) byline.append(' · ' + song.year);
    action.className = 'song-action';
    action.textContent = song.video ? 'Ролик YouTube' : 'Поиск YouTube';
    label.append(code, title);
    link.append(label, action);
    const guitar = document.createElement('details');
    const summary = document.createElement('summary');
    const chordLink = document.createElement('a');
    summary.textContent = 'Аккорды и табы';
    chordLink.href = song.chords || 'https://www.google.com/search?q='
      + encodeURIComponent(query + (song.lang === 'ru' ? ' аккорды табулатура гитара' : ' guitar chords tabs'));
    chordLink.target = '_blank';
    chordLink.rel = 'noopener noreferrer';
    chordLink.textContent = song.chords ? 'Открыть разбор на AmDm' : 'Найти разбор для гитары';
    guitar.append(summary, chordLink);
    row.append(link, byline, guitar);
    return row;
}

function renderSongs() {
  const {matches, query, codeQuery, validCode} = getMatches();
  renderSuggestions(suggestions, matches, selectedArtist || lyricMatches ? '' : query, label => {
    selectedArtist = null;
    search.value = label;
    page = 0;
    renderSongs();
    search.focus();
  });
  const start = page * pageSize;
  const rows = matches.slice(start, start + pageSize).map(({entry}) => songRow(entry.song));
  list.replaceChildren(...rows);
  const active = Boolean(query || selectedArtist || lyricMatches || filters.some(filter => filter.value));
  randomButton.disabled = Boolean(codeQuery) || matches.length === 0;
  if (lastPick && (codeQuery || !matches.some(({entry}) => entry.song === lastPick))) {
    lastPick = null;
    randomPick.hidden = true;
    randomPick.replaceChildren();
  }
  const fewer = active && matches.length > 0 && matches.length < 7;
  count.textContent = codeQuery
    ? (!validCode ? 'Введи ровно четыре цифры: например, 0001.'
      : matches.length ? 'Песня по коду ' + codeQuery + ' · без учёта фильтров.'
        : 'Песни с кодом ' + codeQuery + ' нет в каталоге.')
    : matches.length
    ? 'Песни ' + (start + 1) + '–' + (start + rows.length) + ' из ' + matches.length
      + (fewer ? '. Меньше 7 совпадений: можно продолжить или снять один фильтр.' : '')
    : 'Совпадений нет. Измени запрос или сними один фильтр; условия не сброшены.';
  prev.disabled = page === 0;
  next.disabled = start + pageSize >= matches.length;
  prev.parentElement.hidden = matches.length <= pageSize;
}

for (const [control, event] of [[search, 'input'], [language, 'change'], [mood, 'change'], [genre, 'change'], [era, 'change']]) {
  control.addEventListener(event, () => {
    if (control === search) {
      clearLyrics();
      codeSearch.value = '';
      selectedArtist = null;
    }
    page = 0;
    renderSongs();
  });
}
codeSearch.addEventListener('input', () => {
  // Keep the title query and filters for when the code is cleared.
  clearLyrics();
  page = 0;
  renderSongs();
});
resetFilters.addEventListener('click', () => {
  for (const filter of filters) filter.value = '';
  search.value = '';
  codeSearch.value = '';
  selectedArtist = null;
  lyricInput.value = '';
  clearLyrics();
  lastPick = null;
  randomPick.hidden = true;
  randomPick.replaceChildren();
  page = 0;
  renderSongs();
});
for (const [button, step] of [[prev, -1], [next, 1]]) {
  button.addEventListener('click', () => {
    page += step;
    renderSongs();
    list.querySelector('a')?.focus();
  });
}
randomButton.addEventListener('click', () => {
  const {matches, codeQuery} = getMatches();
  if (codeQuery) return;
  const songsInResults = matches.map(({entry}) => entry.song);
  const pool = songsInResults.length > 1
    ? songsInResults.filter(song => song !== lastPick) : songsInResults;
  if (!pool.length) return;
  lastPick = pool[Math.floor(Math.random() * pool.length)];
  randomPick.replaceChildren(songRow(lastPick));
  randomPick.hidden = false;
  if (!window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
    const die = randomButton.querySelector('.song-die');
    for (const animation of die.getAnimations()) animation.cancel();
    die.animate([
      {transform: 'rotate(-10deg)'},
      {transform: 'translateY(-7px) rotate(14deg)'},
      {transform: 'rotate(-10deg)'}
    ], {duration: 300, easing: 'ease-out'});
  }
});
renderSongs();

const lyricForm = document.querySelector('#lyric-search');
const lyricInput = document.querySelector('#lyric-phrase');
const lyricStatus = document.querySelector('#lyric-status');
const lyricClear = document.querySelector('#lyric-clear');
let lyricIndexRequest;
let lyricRevision = 0;

function lyricHash(text) {
  let value = 2166136261;
  for (const char of text) value = Math.imul(value ^ char.codePointAt(0), 16777619);
  return String(value >>> 0);
}

function lyricScores(words, postings) {
  if (words.length === 1) {
    const word = words[0];
    const hits = new Map((postings[lyricHash(word)] ?? []).map(id => [id, -2]));
    for (const entry of indexed) {
      if (entry.title.split(' ').includes(word)) hits.set(entry.id, -5);
    }
    return hits;
  }
  const result = new Map();
  for (const size of [2, 3]) {
    const hashes = new Set();
    for (let start = 0; start + size <= words.length; start++) {
      hashes.add(lyricHash(words.slice(start, start + size).join(' ')));
    }
    for (const hash of hashes) {
      for (const id of postings[hash] ?? []) {
        const score = result.get(id) ?? {pairs: 0, triples: 0};
        if (size === 2) score.pairs++;
        else score.triples++;
        result.set(id, score);
      }
    }
  }
  const eligible = new Map();
  for (const [id, score] of result) {
    if (words.length === 2 || score.triples || score.pairs >= Math.max(2, Math.ceil((words.length - 1) / 2))) {
      eligible.set(id, -(score.triples * 5 + score.pairs));
    }
  }
  // A remembered title can be followed by words from elsewhere in the song.
  for (const entry of indexed) {
    const titleWords = entry.title.split(' ');
    if (!titleWords.every(word => words.includes(word))) continue;
    const rest = words.filter(word => !titleWords.includes(word));
    if (!rest.length || !rest.every(word => postings[lyricHash(word)]?.includes(entry.id))) continue;
    eligible.set(entry.id, (eligible.get(entry.id) ?? 0) - 3);
  }
  return eligible;
}

function clearLyrics() {
  lyricRevision++;
  lyricMatches = null;
  lyricStatus.textContent = '';
  lyricClear.hidden = true;
}

lyricForm.addEventListener('submit', async event => {
  event.preventDefault();
  const words = normalize(lyricInput.value).split(' ').filter(Boolean);
  const revision = ++lyricRevision;
  if (!words.length) {
    lyricStatus.textContent = 'Введи хотя бы одно слово.';
    return;
  }
  codeSearch.value = '';
  page = 0;
  renderSongs();
  lyricStatus.textContent = 'Ищу похожие строки…';
  lyricClear.hidden = false;
  try {
    lyricIndexRequest ??= fetch('lyrics-index.json?v=7').then(response => {
      if (!response.ok) throw new Error('Index unavailable');
      return response.json();
    }).catch(error => {
      lyricIndexRequest = null;
      throw error;
    });
    const {coverage, postings} = await lyricIndexRequest;
    if (revision !== lyricRevision) return;
    lyricMatches = lyricScores(words, postings);
    selectedArtist = null;
    search.value = '';
    page = 0;
    renderSongs();
    lyricStatus.textContent = lyricMatches.size
      ? 'Найдено по словам: ' + lyricMatches.size + '. Ниже — песни с учётом выбранных фильтров.'
      : 'Совпадений нет среди ' + coverage + ' песен с индексом текста. Попробуй другую фразу.';
  } catch {
    if (revision === lyricRevision) lyricStatus.textContent = 'Индекс текстов не загрузился. Попробуй ещё раз.';
  }
});

lyricClear.addEventListener('click', () => {
  lyricInput.value = '';
  clearLyrics();
  page = 0;
  renderSongs();
  lyricInput.focus();
});

const catalogButtons = [...document.querySelectorAll('.catalog-switch button')];
for (const button of catalogButtons) {
  button.addEventListener('click', () => {
    for (const option of catalogButtons) {
      const active = option === button;
      option.setAttribute('aria-pressed', String(active));
      document.getElementById(option.getAttribute('aria-controls')).hidden = !active;
    }
  });
}

const guitarSearch = document.querySelector('#guitar-query');
const guitarSuggestions = document.querySelector('#guitar-suggestions');
const guitarCount = document.querySelector('#guitar-count');
const guitarList = document.querySelector('#guitar-list');
const guitarPrev = document.querySelector('#guitar-prev');
const guitarNext = document.querySelector('#guitar-next');
const guitarIndex = guitarSongs.map(([artist, title], id) => indexSong({artist, title}, id));
let guitarPage = 0;

function searchGuitar() {
  guitarPage = 0;
  renderGuitar();
}

function renderGuitar() {
  const query = normalize(guitarSearch.value);
  const matches = guitarIndex
    .map(entry => ({entry, score: rank(entry, query)}))
    .filter(match => Number.isFinite(match.score))
    .sort((a, b) => a.score - b.score);
  renderSuggestions(guitarSuggestions, matches, query, label => {
    guitarSearch.value = label;
    searchGuitar();
    guitarSearch.focus();
  });

  const start = guitarPage * pageSize;
  const rows = matches.slice(start, start + pageSize).map(({entry: {song}}) => {
    const row = document.createElement('li');
    const title = document.createElement('strong');
    const artist = document.createElement('span');
    title.textContent = song.title;
    artist.textContent = song.artist;
    row.append(title, artist);
    return row;
  });
  guitarList.replaceChildren(...rows);
  guitarCount.textContent = matches.length
    ? 'Песни ' + (start + 1) + '–' + (start + rows.length) + ' из ' + matches.length
    : 'Совпадений нет. Попробуй другое название или имя исполнителя.';
  guitarPrev.disabled = guitarPage === 0;
  guitarNext.disabled = start + pageSize >= matches.length;
  guitarPrev.parentElement.hidden = matches.length <= pageSize;
}

guitarSearch.addEventListener('input', searchGuitar);
for (const [button, step] of [[guitarPrev, -1], [guitarNext, 1]]) {
  button.addEventListener('click', () => {
    guitarPage += step;
    renderGuitar();
    if (button.disabled) (step > 0 ? guitarPrev : guitarNext).focus();
  });
}
renderGuitar();
